import assert from "node:assert/strict";
import {readFileSync, writeFileSync} from "node:fs";
import {join} from "node:path";
import test from "node:test";
import {MOODS} from "../wallMoods";

// The app groups folder walls by mood on the device with a copy of these rules.
// Run with UPDATE_MOOD_RULES=1 to write the copy again.
const DART_FILE = join(__dirname, "..", "..", "..", "lib", "features", "moods", "domain", "wall_mood_rules_data.dart");

const dartSource = (json: string) => [
  "// Generated by functions/src/__tests__/wallMoodRulesParity.test.ts from functions/src/wallMoods.ts.",
  "// Run `UPDATE_MOOD_RULES=1 node --test lib/__tests__/wallMoodRulesParity.test.js` in functions/ to write it again.",
  "// ignore_for_file: unnecessary_raw_strings",
  "const String wallMoodRulesJson = r'''",
  json,
  "''';",
  "",
].join("\n");

test("the app's mood rules match the server's MOODS", () => {
  const json = JSON.stringify(MOODS);
  if (process.env.UPDATE_MOOD_RULES === "1") writeFileSync(DART_FILE, dartSource(json));
  const source = readFileSync(DART_FILE, "utf8");
  const match = /r'''\n([\s\S]*?)\n'''/.exec(source);
  assert.ok(match, "wall_mood_rules_data.dart has no rules literal");
  assert.deepEqual(JSON.parse(match[1]), JSON.parse(json));
});
